"""Write docs/data_dictionary.md: every CSV in data/ with its row count, columns and a plain description.
Row counts and columns are read from the files, so they cannot drift; descriptions are the DESC table below.
Run from repo root: python scripts/make_data_dictionary.py
"""
import glob
import pandas as pd

DESC = {
    "waste_clean.csv": "State and UT figures in tonnes per day. metric is generated, collected, treated or landfilled. MoHUA 'processed' is stored as treated (our assumption, see definition_crosswalk.csv). Blank value_tpd means not reported; note says what the source printed. year is a financial year.",
    "national_stated.csv": "National totals and percentages exactly as printed in the documents (never computed by us).",
    "reconciliation.csv": "Sum of the state rows against the stated national total for each table; differences under 0.5 tpd are source rounding.",
    "spot_check.csv": "30 random cells with the PDF page and the value read from it (AI-assisted visual read, not a manual hand check).",
    "flags.csv": "Rule failures from scripts/validate.py: state, year, rule, values, plain-English explanation. A flag says two reported figures cannot all be true, not which is wrong.",
    "gap_ranking.csv": "States ranked by the gap between CPCB 2023-24 percent treated and MoHUA 2025-26 percent processed (different years), with MoHUA Dec 2023 and CPCB 2022-23 for context.",
    "funds.csv": "Lok Sabha Q682 annexure: SBM-U 2.0 allocation 2021-2026 and funds utilised or released till 25.11.2024, total and solid-waste component. The table prints no unit.",
    "waste_mohua_2023-12.csv": "MoHUA Lok Sabha Q3198 (21 Dec 2023) state table, same columns as waste_clean.csv. year is 'as on 21-12-2023': the source gives no financial year.",
    "mohua_statements.csv": "MoHUA's own national statements over time, each with its source page.",
    "national_segregation.csv": "National counts from the GFC 2022 dashboard (wards with over 90% door-to-door collection, over 90% source segregation, and others) with computed shares against the stated base.",
    "state_indicators.csv": "Per state and CPCB year: collection percent, uncollected tpd, treated percent, landfill percent, unaccounted percent. Blank inputs give blank outputs.",
    "truck_priority.csv": "States ranked by tonnage left uncollected in CPCB 2023-24. A prioritisation list, not route optimisation.",
    "phantom_tonnes.csv": "Reported figures that cannot all be true, in separate counters (A to E) that must not be added together.",
    "money_vs_mess.csv": "SWM fund utilisation share against CPCB percent treated, with a quadrant split at the medians.",
    "volatility.csv": "How much each state's own reported generated waste moves between documents (highest divided by lowest).",
    "recurrence.csv": "States where the same within-source rule is tripped in two or more years.",
    "audit_priority.csv": "Where an audit would learn most: equal-weight average of five percentile-ranked factors. Not a finding that any state's data is wrong.",
    "definition_crosswalk.csv": "What CPCB and MoHUA each say for the same concept, why the difference matters, and the pages.",
    "city_audit_template.csv": "Empty template with the columns that scripts/audit_city.py expects.",
}
out = ["# Data dictionary", "", "Generated by `scripts/make_data_dictionary.py`. Units are tonnes per day (tpd) unless a column says otherwise. Blank means not reported.", "",
       "| File | Rows | Columns | What it is |", "|---|---|---|---|"]
for f in sorted(glob.glob("data/*.csv")):
    name = f.split("/")[-1].split("\\")[-1]
    d = pd.read_csv(f)
    out.append(f"| `{name}` | {len(d)} | {', '.join('`'+c+'`' for c in d.columns)} | {DESC.get(name, 'TO DESCRIBE')} |")
open("docs/data_dictionary.md", "w", encoding="utf-8").write("\n".join(out) + "\n")
missing = [f for f in glob.glob("data/*.csv") if f.split("/")[-1].split("\\")[-1] not in DESC]
print(len(glob.glob("data/*.csv")), "files; undescribed:", missing or "none")
